import { createRoute, z } from '@hono/zod-openapi'

const IdSchema = z.int().min(1).openapi({ example: 42 }).openapi('Id')

const UUIDv4Schema = z
  .uuid()
  .regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/)
  .length(36)
  .openapi({ example: '9c9de5e8-0a1e-484a-b099-e80766180a6d' })
  .openapi('UUIDv4')

const ShortUUIDSchema = z
  .string()
  .openapi({
    description: 'translation of a uuid v4 with a bigger alphabet to have a shorter uuid',
    example: '2y84q2MQUMWPbiEcxNXMgC',
  })
  .openapi('ShortUUID')

const LiveScheduleSchema = z
  .object({
    startAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Date when the stream is scheduled to air at' }),
  })
  .openapi({ required: [] })
  .openapi('LiveSchedule')

const VideoCategorySetSchema = z
  .int()
  .openapi({
    description: 'category id of the video (see [/videos/categories](#operation/getCategories))',
    example: 15,
  })
  .openapi('VideoCategorySet')

const VideoConstantNumberCategorySchema = z
  .object({
    id: VideoCategorySetSchema.exactOptional(),
    label: z.string().exactOptional().openapi({ example: 'Science & Technology' }),
  })
  .openapi({ required: [] })
  .openapi('VideoConstantNumberCategory')

const VideoLicenceSetSchema = z
  .int()
  .openapi({
    description: 'licence id of the video (see [/videos/licences](#operation/getLicences))',
    example: 2,
  })
  .openapi('VideoLicenceSet')

const VideoConstantNumberLicenceSchema = z
  .object({
    id: VideoLicenceSetSchema.exactOptional(),
    label: z.string().exactOptional().openapi({ example: 'Attribution - Share Alike' }),
  })
  .openapi({ required: [] })
  .openapi('VideoConstantNumberLicence')

const VideoLanguageSetSchema = z
  .string()
  .openapi({
    description: 'language id of the video (see [/videos/languages](#operation/getLanguages))',
    example: 'en',
  })
  .openapi('VideoLanguageSet')

const VideoConstantStringLanguageSchema = z
  .object({
    id: VideoLanguageSetSchema.exactOptional(),
    label: z.string().exactOptional().openapi({ example: 'English' }),
  })
  .openapi({ required: [] })
  .openapi('VideoConstantStringLanguage')

const VideoPrivacySetSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3), z.literal(4), z.literal(5)])
  .openapi({
    description:
      'privacy id of the video (see [/videos/privacies](#operation/getVideoPrivacyPolicies))',
  })
  .openapi('VideoPrivacySet')

const VideoPrivacyConstantSchema = z
  .object({ id: VideoPrivacySetSchema.exactOptional(), label: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('VideoPrivacyConstant')

const ThumbnailSchema = z
  .object({
    fileUrl: z.string().exactOptional(),
    width: z.int().exactOptional(),
    height: z.int().exactOptional(),
    aspectRatio: z.string().exactOptional().openapi({ example: '16:9' }),
  })
  .openapi({ required: [] })
  .openapi('Thumbnail')

const NSFWFlagSchema = z
  .union([z.literal(0), z.literal(1), z.literal(2), z.literal(4)])
  .openapi({
    description:
      '\nNSFW flags (can be combined using bitwise or operator)\n- `0` NONE\n- `1` VIOLENT\n- `2` EXPLICIT_SEX\n',
  })
  .openapi('NSFWFlag')

const VideoAIUsageSetSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3), z.literal(4)])
  .openapi({
    description:
      '**PeerTube >= 9.0** Use of AI in the video, declared by the video creator:\n  - `1` Not specified\n  - `2` No AI-generated content: nothing seen or heard in the video has been generated by AI\n  - `3` Contains AI-generated content: some parts of the video have been generated by AI\n  - `4` AI-generated: the whole video, or most of it, has been generated by AI\n',
  })
  .openapi('VideoAIUsageSet')

const VideoAIUsageConstantSchema = z
  .object({ id: VideoAIUsageSetSchema.exactOptional(), label: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('VideoAIUsageConstant')

const VideoCommercialContentSetSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3)])
  .openapi({
    description:
      '**PeerTube >= 9.0** Commercial content in the video, declared by the video creator:\n  - `1` None\n  - `2` Promotional content: the creator promotes their own products, services or business\n  - `3` Paid partnership: a third party paid, or provided goods or services, in exchange for the promotion\n',
  })
  .openapi('VideoCommercialContentSet')

const VideoCommercialContentConstantSchema = z
  .object({
    id: VideoCommercialContentSetSchema.exactOptional(),
    label: z.string().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoCommercialContentConstant')

const VideoRecommendationScopeSetSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3), z.literal(4)])
  .openapi({
    description:
      'Videos that can be recommended next to a video:\n  - `1` All videos\n  - `2` Only videos of the platform that owns the reference video (or of the current platform if no video is given)\n  - `3` Only videos of the account that owns the reference video\n  - `4` Only videos of the channel of the reference video\n\nThis is a preference of the video owner: applications displaying recommendations may not apply it\n',
  })
  .openapi('VideoRecommendationScopeSet')

const VideoRecommendationScopeConstantSchema = z
  .object({
    id: VideoRecommendationScopeSetSchema.exactOptional(),
    label: z.string().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoRecommendationScopeConstant')

const VideoStateConstantSchema = z
  .object({
    id: z
      .union([
        z.literal(1),
        z.literal(2),
        z.literal(3),
        z.literal(4),
        z.literal(5),
        z.literal(6),
        z.literal(7),
        z.literal(8),
        z.literal(9),
      ])
      .exactOptional()
      .openapi({
        description:
          'The video state:\n- `1`: Published\n- `2`: To transcode\n- `3`: To import\n- `4`: Waiting for live stream\n- `5`: Live ended\n- `6`: To move to an external storage (object storage...)\n- `7`: Transcoding failed\n- `8`: Moving to an external storage failed\n- `9`: To edit using studio edition feature\n',
      }),
    label: z.string().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoStateConstant')

const VideoScheduledUpdateSchema = z
  .object({
    privacy: VideoPrivacySetSchema.exactOptional(),
    updateAt: z.iso.datetime({ offset: true }).openapi({ description: 'When to update the video' }),
  })
  .openapi({ required: ['updateAt'] })
  .openapi('VideoScheduledUpdate')

const ActorImageSchema = z
  .object({
    path: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Deprecated in PeerTube v8.0, use fileUrl instead. Null if the file is stored in object storage: use the non-deprecated field instead.',
        deprecated: true,
      }),
    fileUrl: z.string().exactOptional().openapi({ description: '**PeerTube >= 7.1**' }),
    width: z.int().exactOptional(),
    height: z.int().exactOptional().openapi({ description: '**PeerTube >= 7.3**' }),
    createdAt: z.iso.datetime({ offset: true }).exactOptional(),
    updatedAt: z.iso.datetime({ offset: true }).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('ActorImage')

const AccountSummarySchema = z
  .object({
    id: z.int().exactOptional(),
    name: z.string().exactOptional(),
    displayName: z.string().exactOptional(),
    url: z.url().exactOptional(),
    host: z.hostname().exactOptional(),
    avatars: z.array(ActorImageSchema).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('AccountSummary')

const VideoChannelSummarySchema = z
  .object({
    id: IdSchema.exactOptional(),
    name: z.string().exactOptional(),
    displayName: z.string().exactOptional(),
    url: z.url().exactOptional(),
    host: z.hostname().exactOptional(),
    avatars: z.array(ActorImageSchema).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoChannelSummary')

const VideoSchema = z
  .object({
    id: IdSchema.exactOptional().openapi({ description: 'object id for the video' }),
    uuid: UUIDv4Schema.exactOptional().openapi({
      description: 'universal identifier for the video, that can be used across instances',
    }),
    shortUUID: ShortUUIDSchema.exactOptional(),
    isLive: z.boolean().exactOptional(),
    liveSchedules: z.array(LiveScheduleSchema).exactOptional(),
    createdAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        example: '2017-10-01T10:52:46.396Z',
        description: 'time at which the video object was first drafted',
      }),
    publishedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        example: '2018-10-01T10:52:46.396Z',
        description:
          'time at which the video was marked as ready for playback (with restrictions depending on `privacy`). Usually set after a `state` evolution.',
      }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        example: '2021-05-04T08:01:01.502Z',
        description: "last time the video's metadata was modified",
      }),
    originallyPublishedAt: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        example: '2010-10-01T10:52:46.396Z',
        description:
          'used to represent a date of first publication, prior to the practical publication date of `publishedAt`',
      }),
    category: VideoConstantNumberCategorySchema.exactOptional().openapi({
      description: 'category in which the video is classified',
    }),
    licence: VideoConstantNumberLicenceSchema.exactOptional().openapi({
      description: 'licence under which the video is distributed',
    }),
    language: VideoConstantStringLanguageSchema.exactOptional().openapi({
      description: 'main language used in the video',
    }),
    privacy: VideoPrivacyConstantSchema.exactOptional().openapi({
      description: 'privacy policy used to distribute the video',
    }),
    truncatedDescription: z
      .string()
      .min(3)
      .max(250)
      .nullable()
      .exactOptional()
      .openapi({
        example:
          '**[Want to help to translate this video?](https://weblate.framasoft.org/projects/what-is-peertube-video/)**\\r\\n\\r\\n\n**Take back the control of your videos! [#JoinPeertube](https://joinpeertube.org)**\\r\\n*A decentralized video hosting network, based on fr...\n',
        description: 'truncated description of the video, written in Markdown.\n',
      }),
    duration: z
      .int()
      .exactOptional()
      .openapi({ example: 1419, description: 'duration of the video in seconds' }),
    aspectRatio: z
      .float32()
      .nullable()
      .exactOptional()
      .openapi({
        example: 1.778,
        description: '**PeerTube >= 6.1** Aspect ratio of the video stream',
      }),
    isLocal: z.boolean().exactOptional(),
    name: z
      .string()
      .min(3)
      .max(120)
      .exactOptional()
      .openapi({ description: 'title of the video', example: 'What is PeerTube?' }),
    thumbnailPath: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Deprecated in PeerTube v8.1, use thumbnails instead. Null if the file is stored in object storage: use the non-deprecated field instead.',
        deprecated: true,
      }),
    previewPath: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Deprecated in PeerTube v8.1, use thumbnails instead. Null if the file is stored in object storage: use the non-deprecated field instead.',
        deprecated: true,
      }),
    thumbnails: z
      .array(ThumbnailSchema)
      .exactOptional()
      .openapi({ description: '**PeerTube >= 8.1** Array of thumbnails for the video' }),
    embedPath: z
      .string()
      .exactOptional()
      .openapi({ example: '/videos/embed/a65bc12f-9383-462e-81ae-8207e8b434ee' }),
    views: z.int().exactOptional().openapi({ example: 1337 }),
    likes: z.int().exactOptional().openapi({ example: 42 }),
    dislikes: z.int().exactOptional().openapi({ example: 7 }),
    comments: z
      .int()
      .exactOptional()
      .openapi({ description: '**PeerTube >= 7.2** Number of comments on the video' }),
    nsfw: z.boolean().exactOptional(),
    nsfwFlags: NSFWFlagSchema.exactOptional(),
    nsfwSummary: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '**PeerTube >= 7.2** More information about the sensitive content of the video',
      }),
    aiUsage: VideoAIUsageConstantSchema.exactOptional(),
    commercialContent: VideoCommercialContentConstantSchema.exactOptional(),
    recommendationScope: VideoRecommendationScopeConstantSchema.exactOptional(),
    waitTranscoding: z.boolean().nullable().exactOptional(),
    state: VideoStateConstantSchema.exactOptional().openapi({
      description:
        'represents the internal state of the video processing within the PeerTube instance',
    }),
    scheduledUpdate: VideoScheduledUpdateSchema.nullable().exactOptional(),
    blacklisted: z.boolean().nullable().exactOptional(),
    blacklistedReason: z.string().nullable().exactOptional(),
    account: AccountSummarySchema.exactOptional(),
    channel: VideoChannelSummarySchema.exactOptional(),
    userHistory: z
      .object({ currentTime: z.int().exactOptional() })
      .nullable()
      .exactOptional()
      .openapi({ required: [] }),
  })
  .openapi({ required: [] })
  .openapi('Video')

const UsernameSchema = z
  .string()
  .regex(/\/^[a-z0-9._]+$\//)
  .min(1)
  .max(50)
  .openapi({
    description: 'immutable name of the user, used to find or mention its actor',
    example: 'chocobozzz',
  })
  .openapi('Username')

const ActorSchema = z
  .object({
    id: IdSchema.exactOptional(),
    url: z.url().exactOptional(),
    name: UsernameSchema.exactOptional().openapi({
      description: 'immutable name of the actor, used to find or mention it',
    }),
    avatars: z.array(ActorImageSchema).exactOptional(),
    host: z
      .hostname()
      .exactOptional()
      .openapi({ description: 'server on which the actor is resident' }),
    hostRedundancyAllowed: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({ description: "whether this actor's host allows redundancy of its videos" }),
    followingCount: z
      .int()
      .min(0)
      .exactOptional()
      .openapi({
        description: 'number of actors subscribed to by this actor, as seen by this instance',
      }),
    followersCount: z
      .int()
      .min(0)
      .exactOptional()
      .openapi({ description: 'number of followers of this actor, as seen by this instance' }),
    createdAt: z.iso.datetime({ offset: true }).exactOptional(),
    updatedAt: z.iso.datetime({ offset: true }).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('Actor')

const AccountSchema = ActorSchema.and(
  z
    .object({
      userId: IdSchema.nullable()
        .exactOptional()
        .openapi({ description: 'object id for the user tied to this account' }),
      displayName: z
        .string()
        .min(3)
        .max(120)
        .exactOptional()
        .openapi({ description: 'editable name of the account, displayed in its representations' }),
      description: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({ description: "text or bio displayed on the account's profile" }),
    })
    .openapi({ required: [] }),
).openapi('Account')

const VideoCommentSchema = z
  .object({
    id: IdSchema.exactOptional(),
    url: z.url().exactOptional(),
    text: z
      .string()
      .min(1)
      .exactOptional()
      .openapi({ description: 'Text of the comment', example: 'This video is wonderful!' }),
    threadId: IdSchema.exactOptional(),
    inReplyToCommentId: IdSchema.nullable().exactOptional(),
    videoId: z.lazy(() => VideoSchema).exactOptional(),
    createdAt: z.iso.datetime({ offset: true }).exactOptional(),
    updatedAt: z.iso.datetime({ offset: true }).exactOptional(),
    deletedAt: z.iso.datetime({ offset: true }).nullable().default(null).exactOptional(),
    isDeleted: z.boolean().default(false).exactOptional(),
    heldForReview: z.boolean().exactOptional(),
    totalRepliesFromVideoAuthor: z.int().min(0).exactOptional(),
    totalReplies: z.int().min(0).exactOptional(),
    account: AccountSchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoComment')

type VideoCommentThreadTreeType = {
  comment?: z.infer<typeof VideoCommentSchema>
  children?: VideoCommentThreadTreeType[]
  totalChildren?: number
}

const UsernameChannelSchema = z
  .string()
  .regex(/\/^[a-zA-Z0-9\\-_.:]+$\//)
  .min(1)
  .max(50)
  .openapi({
    description: 'immutable name of the channel, used to interact with its actor',
    example: 'framasoft_videos',
  })
  .openapi('UsernameChannel')

const PasswordSchema = z.string().min(6).max(50).openapi('Password')

const VideoPlaylistPrivacySetSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3)])
  .openapi({
    description:
      'Video playlist privacy policy (see [/video-playlists/privacies](#operation/getPlaylistPrivacyPolicies))',
  })
  .openapi('VideoPlaylistPrivacySet')

const VideoPlaylistPrivacyConstantSchema = z
  .object({ id: VideoPlaylistPrivacySetSchema.exactOptional(), label: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('VideoPlaylistPrivacyConstant')

const VideoPlaylistTypeSetSchema = z
  .union([z.literal(1), z.literal(2)])
  .openapi({ description: 'The video playlist type (Regular = `1`, Watch Later = `2`)' })
  .openapi('VideoPlaylistTypeSet')

const VideoPlaylistTypeConstantSchema = z
  .object({ id: VideoPlaylistTypeSetSchema.exactOptional(), label: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('VideoPlaylistTypeConstant')

const VideoCommentsPolicySetSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3)])
  .openapi({
    description:
      'Comments policy of the video (Enabled = `1`, Disabled = `2`, Requires Approval = `3`)',
  })
  .openapi('VideoCommentsPolicySet')

const VideoCommentsPolicyConstantSchema = z
  .object({ id: VideoCommentsPolicySetSchema.exactOptional(), label: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('VideoCommentsPolicyConstant')

const BlockStatusSchema = z
  .object({
    accounts: z
      .record(
        z.string(),
        z
          .object({
            blockedByServer: z.boolean().exactOptional(),
            blockedByServerSubscription: z.string().exactOptional(),
            blockedByUser: z.boolean().exactOptional(),
          })
          .openapi({ 'x-additionalPropertiesName': 'account', required: [] }),
      )
      .exactOptional(),
    hosts: z
      .record(
        z.string(),
        z
          .object({
            blockedByServer: z.boolean().exactOptional(),
            blockedByServerSubscription: z.string().exactOptional(),
            blockedByUser: z.boolean().exactOptional(),
          })
          .openapi({ 'x-additionalPropertiesName': 'host', required: [] }),
      )
      .exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('BlockStatus')

const NSFWPolicySchema = z.enum(['display', 'warn', 'do_not_list']).openapi('NSFWPolicy')

const UserRoleSchema = z
  .union([z.literal(0), z.literal(1), z.literal(2)])
  .openapi({ description: 'The user role (Admin = `0`, Moderator = `1`, User = `2`)', example: 2 })
  .openapi('UserRole')

const UserAdminFlagsSchema = z
  .union([z.literal(0), z.literal(1)])
  .openapi({
    description: 'Admin flags for the user (None = `0`, Bypass video blocklist = `1`)',
    example: 1,
  })
  .openapi('UserAdminFlags')

const LiveVideoLatencyModeSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3)])
  .openapi({
    description: 'The live latency mode (Default = `1`, High latency = `2`, Small Latency = `3`)',
  })
  .openapi('LiveVideoLatencyMode')

const LiveVideoReplaySettingsSchema = z
  .object({ privacy: VideoPrivacySetSchema.exactOptional() })
  .openapi({ required: [] })
  .openapi('LiveVideoReplaySettings')

const VideoChannelActivityActionSchema = z
  .union([
    z.literal(1),
    z.literal(2),
    z.literal(3),
    z.literal(4),
    z.literal(5),
    z.literal(6),
    z.literal(7),
    z.literal(8),
    z.literal(9),
    z.literal(10),
    z.literal(11),
  ])
  .openapi({
    description:
      'The activity action:\n  - CREATE: 1\n  - UPDATE: 2\n  - DELETE: 3\n  - UPDATE_CAPTIONS: 4\n  - UPDATE_CHAPTERS: 5\n  - UPDATE_PASSWORDS: 6\n  - CREATE_STUDIO_TASKS: 7\n  - UPDATE_SOURCE_FILE: 8\n  - UPDATE_ELEMENTS: 9\n  - REMOVE_CHANNEL_OWNERSHIP: 10\n  - CREATE_CHANNEL_OWNERSHIP: 11\n',
  })
  .openapi('VideoChannelActivityAction')

const VideoChannelActivityTargetSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3), z.literal(4), z.literal(5)])
  .openapi({
    description:
      'The activity target:\n  - VIDEO: 1,\n  - PLAYLIST: 2,\n  - CHANNEL: 3,\n  - CHANNEL_SYNC: 4,\n  - VIDEO_IMPORT: 5\n',
  })
  .openapi('VideoChannelActivityTarget')

const UserExportStateSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3), z.literal(4)])
  .openapi({
    description:
      'The user export state:\n  - `1`: Pending\n  - `2`: Processing\n  - `3`: Completed\n  - `4`: Errored\n',
  })
  .openapi('UserExportState')

const UserImportStateSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3), z.literal(4)])
  .openapi({
    description:
      'The user import state:\n  - `1`: Pending\n  - `2`: Processing\n  - `3`: Completed\n  - `4`: Errored\n',
  })
  .openapi('UserImportState')

const AbuseStateSetSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3)])
  .openapi({ description: 'The abuse state (Pending = `1`, Rejected = `2`, Accepted = `3`)' })
  .openapi('AbuseStateSet')

const AbuseStateConstantSchema = z
  .object({ id: AbuseStateSetSchema.exactOptional(), label: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('AbuseStateConstant')

const AbusePredefinedReasonsSchema = z
  .array(
    z.enum([
      'violentOrAbusive',
      'hatefulOrAbusive',
      'spamOrMisleading',
      'privacy',
      'rights',
      'serverRules',
      'thumbnails',
      'captions',
    ]),
  )
  .openapi({ example: ['spamOrMisleading'] })
  .openapi('AbusePredefinedReasons')

const VideoResolutionSetSchema = z
  .int()
  .openapi({
    description:
      'Video resolution (`0`, `240`, `360`, `720`, `1080`, `1440` or `2160`)\n\n`0` is used as a special value for stillimage videos dedicated to audio, a.k.a. audio-only videos.\n',
    example: 240,
  })
  .openapi('VideoResolutionSet')

const VideoResolutionConstantSchema = z
  .object({
    id: VideoResolutionSetSchema.exactOptional(),
    label: z.string().exactOptional().openapi({ example: '240p' }),
  })
  .openapi({ description: 'resolutions and their labels for the video', required: [] })
  .openapi('VideoResolutionConstant')

const VideoSummarySchema = z
  .object({
    id: IdSchema.exactOptional().openapi({ description: 'object id for the video' }),
    uuid: UUIDv4Schema.exactOptional().openapi({
      description: 'universal identifier for the video, that can be used across instances',
    }),
    shortUUID: ShortUUIDSchema.exactOptional(),
    name: z.string().exactOptional(),
    isLive: z.boolean().exactOptional(),
    nsfw: z.boolean().exactOptional(),
    publishedAt: z.iso.datetime({ offset: true }).exactOptional(),
    thumbnails: z
      .array(ThumbnailSchema)
      .exactOptional()
      .openapi({ description: '**PeerTube >= 8.1** Array of thumbnails for the video' }),
    channel: VideoChannelSummarySchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoSummary')

const PlaylistElementSchema = z
  .object({
    position: z.int().exactOptional(),
    startTimestamp: z.int().exactOptional(),
    stopTimestamp: z.int().exactOptional(),
    video: VideoSchema.nullable().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('PlaylistElement')

const FileStorageSchema = z
  .union([z.literal(0), z.literal(1)])
  .openapi({ description: 'The file storage type:\n  - `0` File system\n  - `1` Object storage\n' })
  .openapi('FileStorage')

const VideoFileSchema = z
  .object({
    id: IdSchema.exactOptional(),
    magnetUri: z
      .url()
      .regex(/\/magnet:\?xt=urn:[a-z0-9]+:[a-z0-9]{32}\/i/)
      .exactOptional()
      .openapi({
        description:
          'magnet URI allowing to resolve the video via BitTorrent without a metainfo file',
      }),
    resolution: VideoResolutionConstantSchema.exactOptional(),
    size: z.int().exactOptional().openapi({ description: 'Video file size in bytes' }),
    torrentUrl: z.url().exactOptional().openapi({ description: 'Direct URL of the torrent file' }),
    torrentDownloadUrl: z
      .url()
      .exactOptional()
      .openapi({
        description:
          'URL endpoint that transfers the torrent file as an attachment (so that the browser opens a download dialog)',
      }),
    fileUrl: z.url().exactOptional().openapi({ description: 'Direct URL of the video' }),
    playlistUrl: z
      .url()
      .exactOptional()
      .openapi({ description: 'Playlist URL of the file if it is owned by a playlist' }),
    fileDownloadUrl: z
      .url()
      .exactOptional()
      .openapi({
        description:
          'URL endpoint that transfers the video file as an attachment (so that the browser opens a download dialog)',
      }),
    fps: z.number().exactOptional().openapi({ description: 'Frames per second of the video file' }),
    width: z
      .number()
      .exactOptional()
      .openapi({ description: '**PeerTube >= 6.1** Video stream width' }),
    height: z
      .number()
      .exactOptional()
      .openapi({ description: '**PeerTube >= 6.1** Video stream height' }),
    metadataUrl: z
      .url()
      .exactOptional()
      .openapi({ description: 'URL dereferencing the output of ffprobe on the file' }),
    hasAudio: z
      .boolean()
      .exactOptional()
      .openapi({ description: '**PeerTube >= 6.2** The file container has an audio stream' }),
    hasVideo: z
      .boolean()
      .exactOptional()
      .openapi({ description: '**PeerTube >= 6.2** The file container has a video stream' }),
    storage: FileStorageSchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoFile')

const VideoStreamingPlaylistsHLSSchema = z
  .object({
    playlistUrl: z.url().exactOptional(),
    segmentsSha256Url: z.url().exactOptional(),
    files: z
      .array(VideoFileSchema)
      .exactOptional()
      .openapi({
        description:
          'Video files associated to this playlist.\n\nThe difference with the root `files` property is that these files are fragmented, so they can be used in this streaming playlist (HLS, etc.)\n',
      }),
    redundancies: z
      .array(z.object({ baseUrl: z.url().exactOptional() }).openapi({ required: [] }))
      .exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoStreamingPlaylistsHLS')

const VideoStreamingPlaylistsSchema = z
  .object({
    id: IdSchema.exactOptional(),
    type: z.literal(1).exactOptional().openapi({ description: 'Playlist type:\n- `1`: HLS\n' }),
  })
  .openapi({ required: [] })
  .and(VideoStreamingPlaylistsHLSSchema)
  .openapi('VideoStreamingPlaylists')

const VideoInfoSchema = z
  .object({
    id: z.lazy(() => VideoSchema).exactOptional(),
    uuid: z.lazy(() => VideoSchema).exactOptional(),
    name: z.lazy(() => VideoSchema).exactOptional(),
    state: z.lazy(() => VideoSchema).exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('VideoInfo')

const ServerErrorSchema = z
  .object({
    type: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'URI identifying the error type. `about:blank` when the error has no specific type. Otherwise it links to the corresponding section of the [Errors](#section/Errors) documentation; the type name itself is also available in `code`.\n',
        example:
          'https://docs.joinpeertube.org/api-rest-reference.html#section/Errors/video_requires_password',
      }),
    detail: z
      .string()
      .exactOptional()
      .openapi({ example: 'Please provide a password to access this password protected video' }),
    status: z.int().exactOptional().openapi({ example: 403 }),
    code: z.string().exactOptional().openapi({ example: 'video_requires_password' }),
  })
  .openapi({ required: [] })
  .openapi('ServerError')

const VideoChannelSchema = ActorSchema.and(
  z
    .object({
      displayName: z
        .string()
        .min(1)
        .max(120)
        .exactOptional()
        .openapi({
          description: 'editable name of the channel, displayed in its representations',
          example: 'Videos of Framasoft',
        }),
      description: z
        .string()
        .min(3)
        .max(1000)
        .nullable()
        .exactOptional()
        .openapi({ example: 'Videos made with <3 by Framasoft' }),
      support: z
        .string()
        .min(3)
        .max(1000)
        .nullable()
        .exactOptional()
        .openapi({
          description:
            'text shown by default on all videos of this channel, to tell the audience how to support it',
          example: 'Please support our work on https://soutenir.framasoft.org/en/ <3',
        }),
      publicEmail: z
        .email()
        .nullable()
        .exactOptional()
        .openapi({ description: 'Public email visible in podcast RSS feeds' }),
      isLocal: z.boolean().exactOptional(),
      updatedAt: z.iso.datetime({ offset: true }).exactOptional(),
      banners: z.array(ActorImageSchema).exactOptional(),
      ownerAccount: AccountSchema.exactOptional(),
      videosCount: z
        .int()
        .exactOptional()
        .openapi({ description: 'only included when `withStats` is true' }),
      viewsPerDay: z
        .array(
          z
            .object({
              date: z.iso.datetime({ offset: true }).exactOptional(),
              views: z.int().exactOptional(),
            })
            .openapi({ required: [] }),
        )
        .exactOptional()
        .openapi({
          description:
            'only included when `withStats` is true. Chronologically ordered, spans the whole `statsDays` range. Each point aggregates `viewsGroupInterval` worth of views, starting at `date`\n',
        }),
      viewsGroupInterval: z
        .enum(['day', 'week', 'month'])
        .exactOptional()
        .openapi({
          description: 'bucket size of `viewsPerDay`, only included when `withStats` is true',
        }),
      totalViews: z
        .int()
        .exactOptional()
        .openapi({
          description:
            'lifetime views of all the channel videos, only included when `withStats` is true',
        }),
    })
    .openapi({ required: [] }),
).openapi('VideoChannel')

const VideoDetailsSchema = VideoSchema.and(
  z
    .object({
      viewers: z
        .int()
        .exactOptional()
        .openapi({ description: 'If the video is a live, you have the amount of current viewers' }),
      description: z
        .string()
        .min(3)
        .max(1000)
        .nullable()
        .exactOptional()
        .openapi({
          example:
            '"**[Want to help to translate this video?](https://weblate.framasoft.org/projects/what-is-peertube-video/)**\\r\\n\\r\\n\n**Take back the control of your videos! [#JoinPeertube](https://joinpeertube.org)**\\r\\n*A decentralized video hosting network,\nbased on free/libre software!*\\r\\n\\r\\n**Animation Produced by:** [LILA](https://libreart.info) - [ZeMarmot Team](https://film.zemarmot.net)\\r\\n\n*Directed by* Aryeom\\r\\n*Assistant* Jehan\\r\\n**Licence**: [CC-By-SA 4.0](https://creativecommons.org/licenses/by-sa/4.0/)\\r\\n\\r\\n\n**Sponsored by** [Framasoft](https://framasoft.org)\\r\\n\\r\\n**Music**: [Red Step Forward](http://play.dogmazic.net/song.php?song_id=52491) - CC-By Ken Bushima\\r\\n\\r\\n\n**Movie Clip**: [Caminades 3: Llamigos](http://www.caminandes.com/) CC-By Blender Institute\\r\\n\\r\\n**Video sources**: https://gitlab.gnome.org/Jehan/what-is-peertube/"\n',
          description: 'full description of the video, written in Markdown.\n',
        }),
      support: z
        .string()
        .min(3)
        .max(1000)
        .nullable()
        .exactOptional()
        .openapi({
          description: 'A text tell the audience how to support the video creator',
          example: 'Please support our work on https://soutenir.framasoft.org/en/ <3',
        }),
      channel: VideoChannelSchema.exactOptional(),
      account: AccountSchema.exactOptional(),
      tags: z
        .array(z.string().min(2).max(30))
        .min(1)
        .max(5)
        .exactOptional()
        .openapi({ example: ['flowers', 'gardening'] }),
      commentsPolicy: VideoCommentsPolicyConstantSchema.exactOptional(),
      downloadEnabled: z.boolean().exactOptional(),
      inputFileUpdatedAt: z.iso
        .datetime({ offset: true })
        .nullable()
        .exactOptional()
        .openapi({
          description:
            'Latest input file update. Null if the file has never been replaced since the original upload',
        }),
      trackerUrls: z
        .array(z.url())
        .exactOptional()
        .openapi({
          description:
            'WebTorrent (`ws://` or `wss://`) and BitTorrent (`http://` or `https://`) trackers of the video\n',
          example: [
            'https://peertube2.cpy.re/tracker/announce',
            'wss://peertube2.cpy.re/tracker/socket',
          ],
        }),
      files: z
        .array(VideoFileSchema)
        .exactOptional()
        .openapi({
          description:
            'Web compatible video files. If Web Video is disabled on the server:\n\n- field will be empty\n- video files will be found in `streamingPlaylists[].files` field\n',
        }),
      streamingPlaylists: z
        .array(VideoStreamingPlaylistsSchema)
        .exactOptional()
        .openapi({
          description:
            'HLS playlists/manifest files. If HLS is disabled on the server:\n\n- field will be empty\n- video files will be found in `files` field\n',
        }),
    })
    .openapi({ required: [] }),
).openapi('VideoDetails')

