const CommentAutoTagPoliciesSchema = z
  .object({
    review: z
      .array(z.string())
      .exactOptional()
      .openapi({ description: 'Auto tags that automatically set the comment in review state' }),
  })
  .openapi({ required: [] })
  .openapi('CommentAutoTagPolicies')

