const AuditLogSchema = z
  .object({
    id: IdSchema.exactOptional(),
    action: AuditLogActionSchema.exactOptional(),
    entityType: AuditLogEntityTypeSchema.exactOptional(),
    entityId: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Id of the audited entity, `null` for the instance configuration' }),
    user: z
      .object({
        id: z
          .int()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              '`null` if the user has been deleted, for remote actors or for entries imported from the legacy audit log files',
          }),
        username: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Username at the time of the action, or the actor handle for remote actors',
          }),
      })
      .exactOptional()
      .openapi({ required: [] }),
    ip: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'IP address of the request, anonymized if `log.anonymize_ip` is enabled',
      }),
    entity: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description: 'Snapshot of the entity after the action (before the action for deletions)',
      }),
    changes: z
      .record(
        z.string(),
        z
          .object({ old: z.any().exactOptional(), new: z.any().exactOptional() })
          .openapi({ required: [] }),
      )
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Only for updates. Keys are dot-separated paths of the changed entity attributes',
      }),
    createdAt: z.iso.datetime({ offset: true }).exactOptional(),
    timestamp: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        deprecated: true,
        description:
          'Same as `createdAt`. Field of the format used before audit logs were stored in the database',
      }),
    level: z
      .literal('audit')
      .exactOptional()
      .openapi({
        deprecated: true,
        description: 'Field of the format used before audit logs were stored in the database',
      }),
    message: z
      .string()
      .exactOptional()
      .openapi({
        deprecated: true,
        description:
          'JSON string containing the `user`, `domain` (entity type), `action`, `entityId`, `ip` and `changes` of the entry, and the properties of the audited entity.\nField of the format used before audit logs were stored in the database\n',
      }),
  })
  .openapi({ required: [] })
  .openapi('AuditLog')

const UserRegistrationStateSchema = z
  .union([z.literal(1), z.literal(2), z.literal(3)])
  .openapi({
    description: 'The registration state (Pending = `1`, Rejected = `2`, Accepted = `3`)',
  })
