export const getDownloadVideosGenerateVideoIdOrUUIDRoute = createRoute({
  method: 'get',
  path: '/download/videos/generate/{videoIdOrUUID}',
  tags: ['Video Download'],
  summary: 'Download video file',
  description:
    'Generate a mp4 container that contains at most 1 video stream and at most 1 audio stream. Mainly used to merge the HLS audio only video file and the HLS video only resolution file.',
  request: {
    params: z.object({ videoIdOrUUID: VideoIdOrUUIDParamsSchema }),
    query: z.object({
      videoFileIds: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            ),
          ),
        )
        .openapi({
          param: {
            name: 'videoFileIds',
            in: 'query',
            required: true,
            description: 'streams of video files to mux in the output',
            schema: { type: 'array', items: { type: 'integer' } },
          },
        }),
      videoFileToken: VideoFileTokenParamsSchema,
    }),
  },
  responses: { 200: { description: 'successful operation' } },
})

