export const postApiV1ServerFollowingRoute = createRoute({
  method: 'post',
  path: '/api/v1/server/following',
  tags: ['Instance Follows'],
  summary: 'Follow a list of actors (PeerTube instance, channel or account)',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              hosts: z
                .array(z.hostname())
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                })
                .exactOptional(),
              handles: z
                .array(z.string())
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                })
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    204: { description: 'successful operation' },
    500: { description: 'cannot follow a non-HTTPS server' },
  },
  security: [{ OAuth2: ['admin'] }],
})

