export const postApiV1UsersTokenRoute = createRoute({
  method: 'post',
  path: '/api/v1/users/token',
  tags: ['Session'],
  summary: 'Login',
  description:
    'With your [client id and secret](#operation/getOAuthClient), you can retrieve an access and refresh tokens.',
  operationId: 'getOAuthToken',
  request: {
    headers: z.object({
      'x-peertube-otp': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'x-peertube-otp',
            in: 'header',
            schema: { type: 'string' },
            required: false,
            description:
              'If the user enabled two factor authentication, you need to provide the OTP code in this header',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .xor([OAuthTokenPasswordSchema, OAuthTokenRefreshTokenSchema])
            .openapi({
              discriminator: {
                propertyName: 'grant_type',
                mapping: {
                  password: '#/components/schemas/OAuthToken-password',
                  refresh_token: '#/components/schemas/OAuthToken-refresh_token',
                },
              },
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              token_type: z.string().exactOptional().openapi({ example: 'Bearer' }),
              access_token: z
                .string()
                .exactOptional()
                .openapi({
                  example: '90286a0bdf0f7315d9d3fe8dabf9e1d2be9c97d0',
                  description: 'valid for 1 day',
                }),
              refresh_token: z
                .string()
                .exactOptional()
                .openapi({
                  example: '2e0d675df9fc96d2e4ec8a3ebbbf45eca9137bb7',
                  description: 'valid for 2 weeks',
                }),
              expires_in: z.int().min(0).exactOptional().openapi({ example: 14399 }),
              refresh_token_expires_in: z
                .int()
                .min(0)
                .exactOptional()
                .openapi({ example: 1209600 }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: {
      description:
        'Disambiguate via `code`:\n- `invalid_client` for an unmatched `client_id`\n- `invalid_grant` for unmatched credentials\n',
    },
    401: {
      description:
        'Disambiguate via `code`:\n- default value for a regular authentication failure\n- `invalid_token` for an expired token\n- `missing_two_factor` if two factor header is missing\n',
    },
  },
})

