export const getApiV1UsersMeVideosImportsRoute = createRoute({
  method: 'get',
  path: '/api/v1/users/me/videos/imports',
  tags: ['Videos', 'My User'],
  summary: 'Get video imports of my user',
  request: {
    query: z.object({
      start: StartParamsSchema,
      count: CountParamsSchema,
      sort: SortParamsSchema,
      includeCollaborations: IncludeCollaborationsParamsSchema,
      videoId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'videoId',
            in: 'query',
            required: false,
            description: 'Filter on import video ID',
            schema: { type: 'integer' },
          },
        }),
      targetUrl: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'targetUrl',
            in: 'query',
            required: false,
            description: 'Filter on import target URL',
            schema: { type: 'string' },
          },
        }),
      videoChannelSyncId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'videoChannelSyncId',
            in: 'query',
            required: false,
            description: 'Filter on imports created by a specific channel synchronization',
            schema: { type: 'number' },
          },
        }),
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            required: false,
            description: 'Search in video names',
            schema: { type: 'string' },
          },
        }),
      stateOneOf: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.lazy(() => VideoImportStateConstantSchema)),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'stateOneOf',
            in: 'query',
            required: false,
            description: 'Filter on import state',
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/VideoImportStateConstant/properties/id' },
            },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'successful operation',
      content: { 'application/json': { schema: VideoImportsListSchema } },
    },
  },
  security: [{ OAuth2: ['user'] }],
})

