export const getApiV1UsersRegistrationsRoute = createRoute({
  method: 'get',
  path: '/api/v1/users/registrations',
  tags: ['Register'],
  summary: 'List registrations',
  operationId: 'listRegistrations',
  request: {
    query: z.object({
      start: StartParamsSchema,
      count: CountParamsSchema,
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'search', in: 'query', required: false, schema: { type: 'string' } },
        }),
      sort: z
        .enum(['-createdAt', 'createdAt', 'state', '-state'])
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['-createdAt', 'createdAt', 'state', '-state'] },
          },
        }),
      stateOneOf: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              UserRegistrationStateSchema,
            ),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'stateOneOf',
            in: 'query',
            required: false,
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/UserRegistrationState' },
            },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              total: z.int().exactOptional().openapi({ example: 1 }),
              data: z.array(UserRegistrationSchema).exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  security: [{ OAuth2: ['admin', 'moderator'] }],
})

