export const postApiV1VideosIdStudioEditRoute = createRoute({
  method: 'post',
  path: '/api/v1/videos/{id}/studio/edit',
  tags: ['Video Transcoding', 'Video'],
  summary: 'Create a studio task',
  description: 'Create a task to edit a video  (cut, add intro/outro etc)',
  request: {
    params: z.object({ id: IdOrUUIDParamsSchema }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z.preprocess(
            (val) => (val === undefined || Array.isArray(val) ? val : [val]),
            z.array(
              z.union([
                z
                  .object({
                    name: z.literal('cut').exactOptional(),
                    options: z
                      .object({
                        start: z
                          .preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            z.int(),
                          )
                          .exactOptional(),
                        end: z
                          .preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            z.int(),
                          )
                          .exactOptional(),
                      })
                      .exactOptional()
                      .openapi({ required: [] }),
                  })
                  .openapi({ title: 'cut', required: [] }),
                z
                  .object({
                    name: z.literal('add-intro').exactOptional(),
                    options: z
                      .object({
                        file: z
                          .file()
                          .exactOptional()
                          .openapi({ type: 'string', format: 'binary' }),
                      })
                      .exactOptional()
                      .openapi({ required: [] }),
                  })
                  .openapi({ title: 'add-intro', required: [] }),
                z
                  .object({
                    name: z.literal('add-outro').exactOptional(),
                    options: z
                      .object({
                        file: z
                          .file()
                          .exactOptional()
                          .openapi({ type: 'string', format: 'binary' }),
                      })
                      .exactOptional()
                      .openapi({ required: [] }),
                  })
                  .openapi({ title: 'add-outro', required: [] }),
                z
                  .object({
                    name: z.literal('add-watermark').exactOptional(),
                    options: z
                      .object({
                        file: z
                          .file()
                          .exactOptional()
                          .openapi({ type: 'string', format: 'binary' }),
                      })
                      .exactOptional()
                      .openapi({ required: [] }),
                  })
                  .openapi({ title: 'add-watermark', required: [] }),
                z
                  .object({
                    name: z.literal('remove-segments').exactOptional(),
                    options: z
                      .object({
                        segments: z.preprocess(
                          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                          z
                            .array(
                              z
                                .object({
                                  start: z.preprocess(
                                    (val) =>
                                      typeof val === 'string' &&
                                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                        ? Number(val)
                                        : val,
                                    z.int().min(0),
                                  ),
                                  end: z.preprocess(
                                    (val) =>
                                      typeof val === 'string' &&
                                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                        ? Number(val)
                                        : val,
                                    z.int().min(1),
                                  ),
                                })
                                .openapi({ required: ['start', 'end'] }),
                            )
                            .min(1),
                        ),
                      })
                      .exactOptional()
                      .openapi({ required: ['segments'] }),
                  })
                  .openapi({ title: 'remove-segments', required: [] }),
              ]),
            ),
          ),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: 'successful operation' },
    400: { description: 'incorrect parameters' },
    404: { description: 'video not found' },
  },
  security: [{ OAuth2: [] }],
})

