export const getApiV1RecommendationsVideosRoute = createRoute({
  method: 'get',
  path: '/api/v1/recommendations/videos',
  tags: ['Video'],
  summary: 'List recommended videos',
  description:
    'Return videos recommended next to a reference video (or general recommendations if no reference video is given).\n\nPeerTube decides the recommendation algorithm: it currently lists videos sharing tags with the reference video\n(excluding videos already watched by the authenticated user), then the latest videos.\nAll returned videos are restricted to the `scope`, which defaults to the `recommendationScope` of the reference video.\n',
  operationId: 'getRecommendationVideos',
  request: {
    query: z.object({
      scope: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          VideoRecommendationScopeSetSchema.openapi({
            param: {
              name: 'scope',
              in: 'query',
              required: false,
              description:
                'Restrict recommended videos. Defaults to the `recommendationScope` of the reference video, or to `1` (all videos) if no reference video is given\n',
              schema: { $ref: '#/components/schemas/VideoRecommendationScopeSet' },
            },
          }),
        )
        .exactOptional(),
      videoId: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(z.xor([IdSchema, UUIDv4Schema, ShortUUIDSchema]))
        .exactOptional()
        .openapi({
          param: {
            name: 'videoId',
            in: 'query',
            required: false,
            description: 'Reference video. Required if `scope` is `3` or `4`',
            schema: {
              oneOf: [
                { $ref: '#/components/schemas/id' },
                { $ref: '#/components/schemas/UUIDv4' },
                { $ref: '#/components/schemas/shortUUID' },
              ],
            },
          },
        }),
      count: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(30),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'count',
            in: 'query',
            required: false,
            description: 'Number of videos to return',
            schema: { type: 'integer', minimum: 1, maximum: 30, default: 10 },
          },
        }),
      excludeVideoIds: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(
              z.preprocess(
                (val) =>
                  typeof val === 'string' &&
                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                    ? Number(val)
                    : val,
                IdSchema,
              ),
            )
            .max(50),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'excludeVideoIds',
            in: 'query',
            required: false,
            description:
              'Videos that must not be recommended (the reference video is always excluded)',
            style: 'form',
            explode: true,
            schema: { type: 'array', maxItems: 50, items: { $ref: '#/components/schemas/id' } },
          },
        }),
      nsfw: NsfwParamsSchema,
      nsfwFlagsIncluded: NsfwFlagsIncludedParamsSchema,
      nsfwFlagsExcluded: NsfwFlagsExcludedParamsSchema,
      aiUsageOneOf: AiUsageOneOfParamsSchema,
    }),
    headers: z.object({ 'x-peertube-video-password': VideoPasswordHeaderParamsSchema }),
  },
  responses: {
    200: {
      description: 'successful operation',
      content: { 'application/json': { schema: VideoListResponseSchema } },
    },
    400: { description: 'invalid parameters or missing `videoId`' },
    401: { description: 'reference video requires authentication or a password' },
    403: { description: 'reference video is not visible by the user or the password is invalid' },
    404: { description: 'reference video not found' },
  },
})

