export const putApiV1VideosIdRoute = createRoute({
  method: 'put',
  path: '/api/v1/videos/{id}',
  tags: ['Video'],
  summary: 'Update a video',
  operationId: 'putVideo',
  request: {
    params: z.object({ id: IdOrUUIDParamsSchema }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              channelId: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'New channel of the video. The channel must be owned by the same account as the previous one. Use the "change ownership" endpoints to give a video to a channel owned by another account on the local PeerTube instance.',
                }),
              thumbnailfile: z
                .file()
                .exactOptional()
                .openapi({ type: 'string', format: 'binary', description: 'Video thumbnail file' }),
              previewfile: z
                .file()
                .exactOptional()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'Deprecated in PeerTube v8.1, use thumbnailfile instead',
                  deprecated: true,
                }),
              category: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoCategorySetSchema,
                )
                .exactOptional(),
              licence: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoLicenceSetSchema,
                )
                .exactOptional(),
              language: VideoLanguageSetSchema.exactOptional(),
              privacy: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoPrivacySetSchema,
                )
                .exactOptional(),
              description: z.string().exactOptional().openapi({ description: 'Video description' }),
              waitTranscoding: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Whether or not we wait transcoding before publish the video',
                }),
              support: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'A text tell the audience how to support the video creator',
                  example: 'Please support our work on https://soutenir.framasoft.org/en/ <3',
                }),
              nsfw: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Whether or not this video contains sensitive content' }),
              nsfwSummary: z
                .any()
                .exactOptional()
                .openapi({
                  description: 'More information about the sensitive content of the video',
                }),
              nsfwFlags: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  NSFWFlagSchema,
                )
                .exactOptional(),
              name: z
                .string()
                .min(3)
                .max(120)
                .exactOptional()
                .openapi({ description: 'Video name' }),
              tags: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string().min(2).max(30)).min(1).max(5),
                )
                .exactOptional()
                .openapi({
                  description: 'Video tags (maximum 5 tags each between 2 and 30 characters)',
                }),
              commentsPolicy: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoCommentsPolicySetSchema,
                )
                .exactOptional(),
              recommendationScope: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoRecommendationScopeSetSchema,
                )
                .exactOptional(),
              aiUsage: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoAIUsageSetSchema,
                )
                .exactOptional(),
              commercialContent: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoCommercialContentSetSchema,
                )
                .exactOptional(),
              downloadEnabled: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Enable or disable downloading for this video' }),
              originallyPublishedAt: ((schema) =>
                z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                z.iso.datetime({ offset: true }).nullable(),
              )
                .exactOptional()
                .openapi({ description: 'Date when the content was originally published' }),
              scheduleUpdate: z
                .object({
                  privacy: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      VideoPrivacySetSchema,
                    )
                    .exactOptional(),
                  updateAt: z.iso
                    .datetime({ offset: true })
                    .openapi({ description: 'When to update the video' }),
                })
                .exactOptional()
                .openapi({ required: ['updateAt'] }),
              videoPasswords: AddVideoPasswordsSchema.exactOptional(),
            })
            .openapi({ required: [] }),
          encoding: {
            thumbnailfile: { contentType: 'image/jpeg' },
            previewfile: { contentType: 'image/jpeg' },
            tags: {},
          },
        },
      },
    },
  },
  responses: { 204: { description: 'successful operation' } },
  security: [{ OAuth2: [] }],
})

