export const postApiV1VideosUploadRoute = createRoute({
  method: 'post',
  path: '/api/v1/videos/upload',
  tags: ['Video', 'Video Upload'],
  summary: 'Upload a video',
  description: 'Uses a single request to upload a video.',
  operationId: 'uploadLegacy',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              name: z
                .string()
                .min(3)
                .max(120)
                .openapi({ description: 'Video name', example: 'What is PeerTube?' }),
              channelId: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(1),
                )
                .openapi({ description: 'Channel id that will contain this video', example: 3 }),
              privacy: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoPrivacySetSchema,
                )
                .exactOptional(),
              category: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoCategorySetSchema,
                )
                .exactOptional(),
              licence: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoLicenceSetSchema,
                )
                .exactOptional(),
              language: VideoLanguageSetSchema.exactOptional(),
              description: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Video description',
                  example:
                    '**[Want to help to translate this video?](https://weblate.framasoft.org/projects/what-is-peertube-video/)**\\r\\n\\r\\n**Take back the control of your videos! [#JoinPeertube](https://joinpeertube.org)**\n',
                }),
              waitTranscoding: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description: 'Whether or not we wait transcoding before publish the video',
                }),
              generateTranscription: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    '**PeerTube >= 6.2** If enabled by the admin, automatically generate a subtitle of the video',
                }),
              support: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'A text tell the audience how to support the video creator',
                  example: 'Please support our work on https://soutenir.framasoft.org/en/ <3',
                }),
              nsfw: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Whether or not this video contains sensitive content' }),
              nsfwSummary: z
                .any()
                .exactOptional()
                .openapi({
                  description: 'More information about the sensitive content of the video',
                }),
              nsfwFlags: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  NSFWFlagSchema,
                )
                .exactOptional(),
              tags: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z
                    .array(z.string().min(2).max(30))
                    .min(1)
                    .max(5)
                    .superRefine((items, ctx) => {
                      const seen = new Map()
                      for (const [i, val] of items.entries()) {
                        const key = JSON.stringify(val)
                        if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                        else seen.set(key, i)
                      }
                    }),
                )
                .exactOptional()
                .openapi({
                  description: 'Video tags (maximum 5 tags each between 2 and 30 characters)',
                  example: ['framasoft', 'peertube'],
                }),
              commentsPolicy: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoCommentsPolicySetSchema,
                )
                .exactOptional(),
              recommendationScope: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoRecommendationScopeSetSchema,
                )
                .exactOptional(),
              aiUsage: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoAIUsageSetSchema,
                )
                .exactOptional(),
              commercialContent: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  VideoCommercialContentSetSchema,
                )
                .exactOptional(),
              downloadEnabled: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Enable or disable downloading for this video' }),
              originallyPublishedAt: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({ description: 'Date when the content was originally published' }),
              scheduleUpdate: z
                .object({
                  privacy: z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      VideoPrivacySetSchema,
                    )
                    .exactOptional(),
                  updateAt: z.iso
                    .datetime({ offset: true })
                    .openapi({ description: 'When to update the video' }),
                })
                .exactOptional()
                .openapi({ required: ['updateAt'] }),
              thumbnailfile: z
                .file()
                .exactOptional()
                .openapi({ type: 'string', format: 'binary', description: 'Video thumbnail file' }),
              previewfile: z
                .file()
                .exactOptional()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'Deprecated in PeerTube v8.1, use thumbnailfile instead',
                  deprecated: true,
                }),
              videoPasswords: AddVideoPasswordsSchema.exactOptional(),
            })
            .openapi({ required: ['channelId', 'name'] })
            .and(
              z
                .object({
                  videofile: z
                    .file()
                    .openapi({ type: 'string', format: 'binary', description: 'Video file' }),
                })
                .openapi({ required: ['videofile'] }),
            ),
          encoding: {
            videofile: {
              contentType:
                'video/mp4, video/webm, video/ogg, video/avi, video/quicktime, video/x-msvideo, video/x-flv, video/x-matroska, application/octet-stream',
            },
            thumbnailfile: { contentType: 'image/jpeg' },
            previewfile: { contentType: 'image/jpeg' },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'successful operation',
      content: { 'application/json': { schema: VideoUploadResponseSchema } },
    },
    403: { description: "video didn't pass upload filter" },
    408: { description: 'upload has timed out' },
    413: {
      description:
        "If the response has no body, it means the reverse-proxy didn't let it through. Otherwise disambiguate via `code`:\n- `quota_reached` for quota limits whether daily or global\n",
      headers: z.object({
        'X-File-Maximum-Size': {
          description: 'Maximum file size for the video',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'Maximum file size for the video',
              param: { required: false },
            }),
        },
      }),
    },
    415: { description: 'video type unsupported' },
    422: { description: 'video unreadable' },
  },
  security: [{ OAuth2: [] }],
})

export const putApiV1VideosUploadResumableRoute = createRoute({
  method: 'put',
  path: '/api/v1/videos/upload-resumable',
  tags: ['Video', 'Video Upload'],
  summary: 'Send chunk for the resumable upload of a video',
  description:
    'Uses [a resumable protocol](https://github.com/kukhariev/node-uploadx/blob/master/proto.md) to continue, pause or resume the upload of a video',
  operationId: 'uploadResumable',
  request: {
    query: z.object({ upload_id: ResumableUploadIdParamsSchema }),
    headers: z.object({
      'Content-Range': ResumableUploadChunkContentRangeHeaderParamsSchema,
      'Content-Length': ResumableUploadChunkContentLengthHeaderParamsSchema,
    }),
    body: {
      content: {
        'application/octet-stream': {
          schema: z.file().openapi({ type: 'string', format: 'binary' }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'last chunk received',
      content: { 'application/json': { schema: VideoUploadResponseSchema } },
      headers: z.object({
        'Content-Length': {
          schema: z
            .number()
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
      }),
    },
    308: {
      description: 'resume incomplete',
      headers: z.object({
        Range: {
          schema: z
            .string()
            .exactOptional()
            .openapi({ param: { required: false }, example: 'bytes=0-262143' }),
        },
        'Content-Length': {
          schema: z
            .number()
            .exactOptional()
            .openapi({ param: { required: false }, example: 0 }),
        },
      }),
    },
    400: {
      description:
        'chunk is smaller than `client.videos.resumableUpload.minChunkSize` of the server config or 1/10,000 of the file size (and is not the last one)',
    },
    403: { description: "video didn't pass upload filter" },
    404: { description: 'upload not found' },
    409: { description: "chunk doesn't match range" },
    422: { description: 'video unreadable' },
    429: { description: 'too many concurrent requests' },
    503: {
      description: 'upload is already being processed',
      headers: z.object({
        'Retry-After': {
          schema: z
            .number()
            .exactOptional()
            .openapi({ param: { required: false }, example: 300 }),
        },
      }),
    },
  },
  security: [{ OAuth2: [] }],
})

export const postApiV1VideosUploadResumableRoute = createRoute({
  method: 'post',
  path: '/api/v1/videos/upload-resumable',
  tags: ['Video', 'Video Upload'],
  summary: 'Initialize the resumable upload of a video',
  description:
    'Uses [a resumable protocol](https://github.com/kukhariev/node-uploadx/blob/master/proto.md) to initialize the upload of a video',
  operationId: 'uploadResumableInit',
  request: {
    headers: z.object({
      'X-Upload-Content-Length': ResumableUploadInitContentLengthHeaderParamsSchema,
      'X-Upload-Content-Type': ResumableUploadInitContentTypeHeaderParamsSchema,
    }),
    body: { content: { 'application/json': { schema: VideoUploadRequestResumableSchema } } },
  },
  responses: {
    200: {
      description:
        'file already exists, send a [`resume`](https://github.com/kukhariev/node-uploadx/blob/master/proto.md) request instead',
    },
    201: {
      description: 'created',
      headers: z.object({
        Location: {
          schema: z
            .url()
            .exactOptional()
            .openapi({
              param: { required: false },
              example: '/api/v1/videos/upload-resumable?upload_id=471e97554f21dec3b8bb5d4602939c51',
            }),
        },
        'Content-Length': {
          schema: z
            .number()
            .exactOptional()
            .openapi({ param: { required: false }, example: 0 }),
        },
      }),
    },
    413: {
      description:
        'Disambiguate via `code`:\n- `max_file_size_reached` for the absolute file size limit\n- `quota_reached` for quota limits whether daily or global\n',
    },
    415: { description: 'video type unsupported' },
  },
  security: [{ OAuth2: [] }],
})

export const deleteApiV1VideosUploadResumableRoute = createRoute({
  method: 'delete',
  path: '/api/v1/videos/upload-resumable',
  tags: ['Video', 'Video Upload'],
  summary: 'Cancel the resumable upload of a video, deleting any data uploaded so far',
  description:
    'Uses [a resumable protocol](https://github.com/kukhariev/node-uploadx/blob/master/proto.md) to cancel the upload of a video',
  operationId: 'uploadResumableCancel',
  request: {
    query: z.object({ upload_id: ResumableUploadIdParamsSchema }),
    headers: z.object({
      'Content-Length': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .openapi({
          param: {
            name: 'Content-Length',
            in: 'header',
            required: true,
            schema: { type: 'number', example: 0 },
          },
          example: 0,
        }),
    }),
  },
  responses: {
    204: {
      description: 'upload cancelled',
      headers: z.object({
        'Content-Length': {
          schema: z
            .number()
            .exactOptional()
            .openapi({ param: { required: false }, example: 0 }),
        },
      }),
    },
    404: { description: 'upload not found' },
  },
  security: [{ OAuth2: [] }],
})

