export const putApiV1VideosIdSourceReplaceResumableRoute = createRoute({
  method: 'put',
  path: '/api/v1/videos/{id}/source/replace-resumable',
  tags: ['Video', 'Video Upload'],
  summary: 'Send chunk for the resumable replacement of a video',
  description:
    '**PeerTube >= 6.0** Uses [a resumable protocol](https://github.com/kukhariev/node-uploadx/blob/master/proto.md) to continue, pause or resume the replacement of a video',
  operationId: 'replaceVideoSourceResumable',
  request: {
    params: z.object({ id: IdOrUUIDParamsSchema }),
    query: z.object({ upload_id: ResumableUploadIdParamsSchema }),
    headers: z.object({
      'Content-Range': ResumableUploadChunkContentRangeHeaderParamsSchema,
      'Content-Length': ResumableUploadChunkContentLengthHeaderParamsSchema,
    }),
    body: {
      content: {
        'application/octet-stream': {
          schema: z.file().openapi({ type: 'string', format: 'binary' }),
        },
      },
    },
  },
  responses: {
    204: { description: 'last chunk received: successful operation' },
    308: {
      description: 'resume incomplete',
      headers: z.object({
        Range: {
          schema: z
            .string()
            .exactOptional()
            .openapi({ param: { required: false }, example: 'bytes=0-262143' }),
        },
        'Content-Length': {
          schema: z
            .number()
            .exactOptional()
            .openapi({ param: { required: false }, example: 0 }),
        },
      }),
    },
    400: {
      description:
        'chunk is smaller than `client.videos.resumableUpload.minChunkSize` of the server config or 1/10,000 of the file size (and is not the last one)',
    },
    403: { description: "video didn't pass file replacement filter" },
    404: { description: 'replace upload not found' },
    409: { description: "chunk doesn't match range" },
    422: { description: 'video unreadable' },
    429: { description: 'too many concurrent requests' },
    503: {
      description: 'upload is already being processed',
      headers: z.object({
        'Retry-After': {
          schema: z
            .number()
            .exactOptional()
            .openapi({ param: { required: false }, example: 300 }),
        },
      }),
    },
  },
  security: [{ OAuth2: [] }],
})

export const postApiV1VideosIdSourceReplaceResumableRoute = createRoute({
  method: 'post',
  path: '/api/v1/videos/{id}/source/replace-resumable',
  tags: ['Video', 'Video Upload'],
  summary: 'Initialize the resumable replacement of a video',
  description:
    '**PeerTube >= 6.0** Uses [a resumable protocol](https://github.com/kukhariev/node-uploadx/blob/master/proto.md) to initialize the replacement of a video',
  operationId: 'replaceVideoSourceResumableInit',
  request: {
    params: z.object({ id: IdOrUUIDParamsSchema }),
    headers: z.object({
      'X-Upload-Content-Length': ResumableUploadInitContentLengthHeaderParamsSchema,
      'X-Upload-Content-Type': ResumableUploadInitContentTypeHeaderParamsSchema,
    }),
    body: { content: { 'application/json': { schema: VideoReplaceSourceRequestResumableSchema } } },
  },
  responses: {
    200: {
      description:
        'file already exists, send a [`resume`](https://github.com/kukhariev/node-uploadx/blob/master/proto.md) request instead',
    },
    201: {
      description: 'created',
      headers: z.object({
        Location: {
          schema: z
            .url()
            .exactOptional()
            .openapi({ param: { required: false } }),
        },
        'Content-Length': {
          schema: z
            .number()
            .exactOptional()
            .openapi({ param: { required: false }, example: 0 }),
        },
      }),
    },
    413: {
      description:
        'Disambiguate via `code`:\n- `max_file_size_reached` for the absolute file size limit\n- `quota_reached` for quota limits whether daily or global\n',
    },
    415: { description: 'video type unsupported' },
  },
  security: [{ OAuth2: [] }],
})

