export const postApiV1AbusesRoute = createRoute({
  method: 'post',
  path: '/api/v1/abuses',
  tags: ['Abuses'],
  summary: 'Report an abuse',
  description:
    'You cannot report a video that you own or on which you are a collaborator (video channel editor).\n',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              reason: z
                .string()
                .min(2)
                .max(3000)
                .openapi({ description: 'Reason why the user reports this video' }),
              predefinedReasons: PredefinedAbuseReasonsSchema.exactOptional(),
              video: z
                .object({
                  id: z
                    .lazy(() => VideoSchema)
                    .exactOptional()
                    .openapi({ description: 'Video id to report' }),
                  startAt: z
                    .int()
                    .min(0)
                    .exactOptional()
                    .openapi({
                      description: 'Timestamp in the video that marks the beginning of the report',
                    }),
                  endAt: z
                    .int()
                    .min(0)
                    .exactOptional()
                    .openapi({
                      description: 'Timestamp in the video that marks the ending of the report',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              comment: z
                .object({
                  id: IdSchema.exactOptional().openapi({ description: 'Comment id to report' }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              account: z
                .object({
                  id: z.int().exactOptional().openapi({ description: 'Account id to report' }),
                })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: ['reason'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              abuse: z
                .object({ id: IdSchema.exactOptional() })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: { description: 'incorrect request parameters' },
    403: { description: 'cannot report a video you own or that you collaborate on' },
  },
  security: [{ OAuth2: [] }],
})

