export const postApiV1RunnersJobsJobUUIDUpdateRoute = createRoute({
  method: 'post',
  path: '/api/v1/runners/jobs/{jobUUID}/update',
  tags: ['Runner Jobs'],
  summary: 'Update job',
  description: 'API used by PeerTube runners',
  request: {
    params: z.object({ jobUUID: JobUUIDParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              runnerToken: z.string(),
              jobToken: z.string(),
              progress: z
                .int()
                .exactOptional()
                .openapi({ description: 'Update job progression percentage (optional)' }),
              payload: z
                .union([
                  z
                    .object({
                      type: z.enum(['add-chunk', 'remove-chunk']).exactOptional(),
                      masterPlaylistFile: z
                        .file()
                        .exactOptional()
                        .openapi({ type: 'string', format: 'binary' }),
                      resolutionPlaylistFile: z
                        .file()
                        .exactOptional()
                        .openapi({ type: 'string', format: 'binary' }),
                      resolutionPlaylistFilename: z.string().exactOptional(),
                      videoChunkFile: z
                        .file()
                        .exactOptional()
                        .openapi({ type: 'string', format: 'binary' }),
                      videoChunkFilename: z.string().exactOptional(),
                    })
                    .openapi({
                      description: 'Provide live transcoding chunks update',
                      required: [],
                    }),
                ])
                .exactOptional(),
            })
            .openapi({ required: ['runnerToken', 'jobToken'] }),
        },
      },
    },
  },
  responses: { 204: { description: 'successful operation' } },
})

