export const getApiV1RunnersJobsRoute = createRoute({
  method: 'get',
  path: '/api/v1/runners/jobs',
  tags: ['Runner Jobs'],
  summary: 'List jobs',
  request: {
    query: z.object({
      start: StartParamsSchema,
      count: CountParamsSchema,
      sort: RunnerJobSortParamsSchema,
      search: SearchParamsSchema,
      stateOneOf: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              RunnerJobStateSchema,
            ),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'stateOneOf',
            in: 'query',
            required: false,
            schema: { type: 'array', items: { $ref: '#/components/schemas/RunnerJobState' } },
          },
        }),
      typeOneOf: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(RunnerJobTypeSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'typeOneOf',
            in: 'query',
            required: false,
            schema: { type: 'array', items: { $ref: '#/components/schemas/RunnerJobType' } },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              total: z.int().exactOptional().openapi({ example: 1 }),
              data: z.array(RunnerJobAdminSchema).exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  security: [{ OAuth2: ['admin'] }],
})

